/* Fluid Heading using clamp() */
.fluid-heading {
  font-size: clamp(1.2rem, 4vw, 2.2rem);
  color: #38bdf8;
  font-weight: 900;
  margin-bottom: 12px;
}

/* Precise Width using calc() */
.calc-box {
  width: calc(100% - 30px);
  margin: 0 auto;
  background: #1e293b;
  color: #94a3b8;
  padding: 12px;
  border-radius: 8px;
  font-size: 13px;
}

.form-container {
  background: #090d16;
  padding: 24px;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  font-family: sans-serif;
  color: white;
}

.field-card {
  background: #1e293b;
  padding: 16px;
  border-radius: 8px;
  border: 2px solid transparent;
  transition: all 0.2s;
}

/* The Magic :has() Parent Selector */
.field-card:has(input:invalid) {
  border-color: #ef4444; /* Highlights entire card in Red! */
  background: rgba(239, 68, 68, 0.08);
}

.field-card:has(input:valid) {
  border-color: #10b981; /* Highlights card in Green! */
}

label {
  display: block;
  font-size: 13px;
  margin-bottom: 6px;
  color: #cbd5e1;
}

input {
  width: 100%;
  background: #0f172a;
  border: 1px solid #334155;
  color: white;
  padding: 8px 12px;
  border-radius: 6px;
  box-sizing: border-box;
}

.glass-scene {
  position: relative;
  height: 220px;
  background: #030712;
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: sans-serif;
}

/* Colorful Glowing Orbs Behind Glass */
.ambient-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
}

.orb-1 {
  width: 120px;
  height: 120px;
  background: #38bdf8;
  top: 20px;
  left: 40px;
}

.orb-2 {
  width: 140px;
  height: 140px;
  background: #ec4899;
  bottom: 10px;
  right: 50px;
}

/* The Frosted Glass Card */
.glass-card {
  position: relative;
  z-index: 10;
  width: 280px;
  padding: 24px;
  border-radius: 16px;

  /* The 3 Golden Rules of Glassmorphism */
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.15);

  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  color: white;
}

.pill {
