/* 1. Single Line Ellipsis Formula */
.truncate-text {
  max-width: 260px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  background: #1e293b;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 13px;
  color: #94a3b8;
}

/* 2. Custom Scrollbar Styling */
.scroll-box {
  height: 90px;
  overflow-y: auto;
  background: #020617;
  padding: 10px 14px;
  border-radius: 6px;
  border: 1px solid #1e293b;
  font-size: 13px;
  color: #cbd5e1;
}

.scroll-box p {
  margin-bottom: 6px;
}

/* Scrollbar Track & Thumb */
.scroll-box::-webkit-scrollbar {
  width: 6px;
}

.scroll-box::-webkit-scrollbar-track {
  background: #0f172a;
}

.scroll-box::-webkit-scrollbar-thumb {
  background: #38bdf8;
  border-radius: 10px;
}

